mapper.select:
SELECT  FROM light_class_course_schedules
WHERE deleted_at IS NULL AND school_class_id = #{schoolClassId}
ORDER BY starts_at

mapper.update:
UPDATE light_class_course_schedules SET deleted_at=(CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version=version+1,
    update_user_id=#{et.updateUserId}, update_time=#{et.updateTime}
WHERE id=#{et.id} AND tenant_id=#{et.tenantId} AND deleted_at IS NULL AND version=#{MP_OPTLOCK_VERSION_ORIGINAL}
